<script setup lang="ts">
/**
 * A segmented time-of-day field with no popup (`design/components/time-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/time-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useId, useTemplateRef, watch } from 'vue'

import {
  agentMember,
  agentTime,
  eraseSegment,
  fieldSegments,
  stepSegment,
  timeDraft,
  timeFieldValue,
  typeIntoSegment,
  type Time,
} from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/time-input.module.css'

export interface TimeInputProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  defaultValue?: Time | null
  disabled?: boolean
  /**
   * The segment list: `'minute'` is `[hh] [mm]`, and `'hour'` drops the minute segment. Seconds
   * are not offered, because no known screen edits them, and options are added only when needed.
   */
  granularity?: 'hour' | 'minute'
  /**
   * The locale decides by default, and this prop overrides it. `12` renders the dayPeriod
   * segment, and `24` never does.
   */
  hourCycle?: 12 | 24
  id?: string
  invalid?: boolean
  /**
   * Sets the segment order, the day period names and the separator.
   */
  locale?: string
  /**
   * Serializes the ISO-8601 time in `Time`'s own format, such as `"09:30:00"`.
   */
  name?: string
  /**
   * Keeps segments focusable and selectable, but arrows and digits do not edit.
   */
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * `@internationalized/date`'s `Time`: a plain time of day with no date and no time zone, never
   * a JS `Date` (Calendar's law). The field edits down to its granularity. Finer fields in a
   * supplied value (seconds on a `Time` the app built) are kept unchanged, never silently set to
   * zero.
   */
  value?: Time | null
}

defineOptions({ name: 'TimeInput', inheritAttrs: false, controlKind: 'group' })

const props = withDefaults(defineProps<TimeInputProps>(), {
  ariaRequired: undefined,
  disabled: false,
  granularity: 'minute',
  invalid: false,
  readOnly: false,
  size: 'md',
})
const emit = defineEmits<{ change: [value: Time | null] }>()
const uid = useId()
const browserLanguage = ref(undefined as string | undefined)
const draft = ref(
  timeDraft(props.value !== undefined ? props.value : props.defaultValue, {
    locale: props.locale ?? browserLanguage.value ?? 'en-US',
    parts: props.granularity === 'hour' ? (['hour'] as const) : (['hour', 'minute'] as const),
    hourCycle: props.hourCycle,
  }),
)
const typed = ref('')
const reported = ref(
  (props.value !== undefined ? props.value : props.defaultValue)?.toString() ?? '',
)
const field = useTemplateRef<HTMLElement>('field')
const language = computed(() => props.locale ?? browserLanguage.value ?? 'en-US')
const fieldOptions = computed(() => ({
  locale: language.value,
  parts: props.granularity === 'hour' ? (['hour'] as const) : (['hour', 'minute'] as const),
  hourCycle: props.hourCycle,
}))
const segments = computed(() => fieldSegments(draft.value, fieldOptions.value))
const kept = computed(() => (props.value !== undefined ? props.value : props.defaultValue) ?? null)
const current = computed(() => timeFieldValue(draft.value, fieldOptions.value, kept.value))
const commit = computed(() => (next: ReturnType<typeof timeDraft>): void => {
  draft.value = next
  const after = timeFieldValue(next, fieldOptions.value, kept.value)
  const text = after?.toString() ?? ''
  if (text !== reported.value) {
    reported.value = text
    emit('change', after)
  }
})
const segmentName = computed(() => (type: string): string => {
  try {
    return new Intl.DisplayNames(language.value, { type: 'dateTimeField' }).of(type) ?? type
  } catch {
    return type
  }
})
const moveSegment = computed(() => (from: EventTarget | null, step: number): void => {
  if (!(from instanceof HTMLElement)) return
  const all = [
    ...(from.closest('[role="group"]')?.querySelectorAll<HTMLElement>('[data-segment]') ?? []),
  ]
  all[all.indexOf(from) + step]?.focus()
})
const segmentKeys = computed(
  () =>
    (event: KeyboardEvent, segment: ReturnType<typeof fieldSegments>[number]): void => {
      if (segment.type === 'literal') return
      if (event.key === 'ArrowLeft' || event.key === 'ArrowRight') {
        event.preventDefault()
        typed.value = ''
        moveSegment.value(
          event.currentTarget,
          (event.key === 'ArrowRight') ===
            (getComputedStyle(event.currentTarget as HTMLElement).direction !== 'rtl')
            ? 1
            : -1,
        )
        return
      }
      if (event.ctrlKey || event.metaKey || event.key === 'Tab') return
      const editable = !props.disabled && !props.readOnly
      if (event.key === 'ArrowUp' || event.key === 'ArrowDown') {
        event.preventDefault()
        typed.value = ''
        if (editable)
          commit.value(
            stepSegment(
              draft.value,
              segment.type,
              event.key === 'ArrowUp' ? 1 : -1,
              fieldOptions.value,
            ),
          )
        return
      }
      if (event.key === 'Backspace' || event.key === 'Delete') {
        event.preventDefault()
        typed.value = ''
        if (!editable) return
        if (draft.value[segment.type] === undefined) moveSegment.value(event.currentTarget, -1)
        else commit.value(eraseSegment(draft.value, segment.type, fieldOptions.value))
        return
      }
      if (event.key.length !== 1) return
      event.preventDefault()
      if (editable)
        ((key: string): void => {
          const next = typeIntoSegment(
            draft.value,
            segment.type,
            typed.value,
            key,
            fieldOptions.value,
          )
          typed.value = next.typed
          commit.value(next.draft)
          if (next.advance) moveSegment.value(event.currentTarget, 1)
        })(event.key)
    },
)
const segmentInput = computed(
  () =>
    (event: Event, segment: ReturnType<typeof fieldSegments>[number]): void => {
      event.preventDefault()
      if (segment.type === 'literal' || !(!props.disabled && !props.readOnly)) return
      const data = (event as InputEvent).data ?? ''
      for (const key of data) {
        const next = typeIntoSegment(
          draft.value,
          segment.type,
          typed.value,
          key,
          fieldOptions.value,
        )
        typed.value = next.typed
        commit.value(next.draft)
        if (next.advance) {
          moveSegment.value(event.currentTarget, 1)
          break
        }
      }
    },
)
const effect1 = () => {
  ;((browserLanguage.value = globalThis.navigator?.language),
    props.locale === undefined &&
      (draft.value = timeDraft(props.value !== undefined ? props.value : props.defaultValue, {
        locale: props.locale ?? browserLanguage.value ?? 'en-US',
        parts: props.granularity === 'hour' ? (['hour'] as const) : (['hour', 'minute'] as const),
        hourCycle: props.hourCycle,
      })))
}
onMounted(effect1)
const effect2 = () => {
  props.value !== undefined &&
    (props.value !== null || current.value !== null) &&
    ((draft.value = timeDraft(props.value, fieldOptions.value)),
    (reported.value = props.value?.toString() ?? ''))
}
watch(() => props.value, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'TimeInput',
    element: () => field.value,
    state: () => ({
      value: current.value?.toString() ?? '',
      disabled: props.disabled,
      invalid: props.invalid,
      readonly: props.readOnly,
    }),
    actions: {
      set: {
        argument: 'text',
        run: (value) =>
          (() => {
            if (props.readOnly) throw new Error('The field is read-only.')
            commit.value(timeDraft(agentTime(value, props.granularity), fieldOptions.value))
          })(),
      },
      clear: () =>
        (() => {
          if (props.readOnly) throw new Error('The field is read-only.')
          commit.value({})
        })(),
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div
    ref="field"
    :class="styles.field"
    role="group"
    :id="id"
    :aria-label="ariaLabel"
    :aria-labelledby="ariaLabelledby"
    :aria-describedby="ariaDescribedby"
    :aria-disabled="disabled ? 'true' : undefined"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-readonly="readOnly ? '' : undefined"
    data-member="time-input"
  >
    <!-- segments -->
    <div :class="styles.segments">
      <template v-for="(segment, at) in segments" :key="`time-${segment.type}-${at}`">
        <!-- separator -->
        <span v-if="segment.type === 'literal'" :class="styles.separator" aria-hidden="true">
          {{ segment.text }}
        </span>
        <!-- segment -->
        <div
          v-else
          :class="styles.segment"
          role="spinbutton"
          :id="`${uid}-time-${segment.type}`"
          :aria-label="segmentName(segment.type)"
          :aria-labelledby="
            ariaLabelledby ? `${ariaLabelledby} ${uid}-time-${segment.type}` : undefined
          "
          :aria-describedby="ariaDescribedby"
          :aria-valuenow="segment.placeholder ? undefined : segment.value"
          :aria-valuemin="segment.min"
          :aria-valuemax="segment.max"
          :aria-valuetext="segment.placeholder ? 'Empty' : segment.text"
          :aria-required="ariaRequired ? 'true' : undefined"
          :aria-readonly="readOnly ? 'true' : undefined"
          :aria-disabled="disabled ? 'true' : undefined"
          :aria-invalid="invalid ? 'true' : undefined"
          :contenteditable="!disabled && !readOnly ? 'true' : undefined"
          :inputmode="segment.type === 'dayPeriod' ? undefined : 'numeric'"
          spellcheck="false"
          :tabindex="disabled ? undefined : '0'"
          :data-segment="segment.type"
          :data-placeholder="segment.placeholder ? '' : undefined"
          :data-disabled="disabled ? '' : undefined"
          @focus="typed = ''"
          @keydown="segmentKeys($event, segment)"
          @beforeinput="segmentInput($event, segment)"
        >
          {{ segment.text }}
        </div>
      </template>
    </div>
    <input
      v-if="name !== undefined"
      type="hidden"
      :name="name"
      :value="current?.toString() ?? ''"
      :disabled="disabled ? true : undefined"
    />
  </div>
</template>
